            return $"{item.Name}";
        }
        /// <summary>One-shot Create + MountFromInventoryEquipmentUserDataAsync (no subscription).</summary>
        public static async Task<EquipmentBinderCollection> CreateFromInventoryEquipmentUserDataAsync(
            Gs2Domain gs2,
            IGameSession session,
            CancellationToken cancellationToken = default)
        {
            var coll = new EquipmentBinderCollection(gs2, session);
            await coll.MountFromInventoryEquipmentUserDataAsync(cancellationToken);
            return coll;
        }

        public async Task MountFromInventoryEquipmentUserDataAsync(CancellationToken cancellationToken = default)
        {
            ThrowIfDisposed();
            cancellationToken.ThrowIfCancellationRequested();
            var arrayLoader = new ItemSetArrayLoader("Equipment", "Equipment");
            var items = await arrayLoader.Load(_gs2, _session);
            cancellationToken.ThrowIfCancellationRequested();
            await ReconcileFromInventoryEquipmentUserItems(items, attachChildSubscribe: false, cancellationToken);
            _mounted = true;
        }

        public void SubscribeFromInventoryEquipmentUserData(Action? onChange = null, Action<Exception>? onError = null)
        {
            ThrowIfDisposed();
            if (_subscriptionActive) throw new InvalidOperationException("Already subscribed");
            _subscriptionActive = true;
            // Consumer-facing notification, wrapped once so a throwing consumer
            // callback routes to onError (or Debug) instead of escaping the
            // loader's async-void chain.
            Action notify = () =>
            {
                try { onChange?.Invoke(); }
                catch (Exception ex) { if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex); }
            };
            _onChange = notify;
            foreach (var b in _binders) b.Subscribe(notify);
            var arrayLoader = new ItemSetArrayLoader("Equipment", "Equipment");
            _unsubscribers.Add(arrayLoader.Subscribe(
                _gs2,
                _session,
                async (_, _, items) =>
                {
                    if (_disposed) return;
                    try
                    {
                        await ReconcileFromInventoryEquipmentUserItems(items, attachChildSubscribe: true, CancellationToken.None);
                    }
                    catch (Exception ex)
                    {
                        if (onError != null) onError(ex); else UnityEngine.Debug.LogException(ex);
                    }
                },
                notify
            ));
        }

        private async Task ReconcileFromInventoryEquipmentUserItems(IList<EzItemSet> items, bool attachChildSubscribe, CancellationToken cancellationToken)
        {
            var seen = new HashSet<string>();
            foreach (var item in items)
            {
                if (_disposed) return;
                var rowKey = ExtractInventoryEquipmentUserRowKey(item);
                if (rowKey == null) continue;
                seen.Add(rowKey);
                if (_bindersByRowKey.TryGetValue(rowKey, out var existing))
                {
                    ApplyInventoryEquipmentUserItemTo(existing.MutableModel, item);
                }
                else
                {
                    var binder = await BuildBinderFromInventoryEquipmentUserItem(item, cancellationToken);
                    if (_disposed)
                    {
                        binder.Dispose();
                        return;
                    }
                    if (_bindersByRowKey.TryGetValue(rowKey, out var raced))
                    {
                        ApplyInventoryEquipmentUserItemTo(raced.MutableModel, item);
                        binder.Dispose();
                        continue;
                    }
                    if (attachChildSubscribe) binder.Subscribe(_onChange);
                    _bindersByRowKey[rowKey] = binder;
                    _binders.Add(binder);
                    ItemAdded?.Invoke(binder);
                }
            }
            if (_bindersByRowKey.Count > seen.Count)
            {
                var toRemove = new List<string>();
                foreach (var kv in _bindersByRowKey)
                {
                    if (!seen.Contains(kv.Key)) toRemove.Add(kv.Key);
                }
                // Detach every stale binder before callbacks; a callback may dispose this Collection.
                var pendingRemovals = new List<Action>();
                foreach (var rowKey in toRemove)
                {
                    if (!_bindersByRowKey.TryGetValue(rowKey, out var binder)) continue;
                    _bindersByRowKey.Remove(rowKey);
                    _binders.Remove(binder);
                    var detachedBinder = binder;
                    // Notify while the binder is live; the Collection retains disposal ownership.
                    pendingRemovals.Add(() =>
                    {
                        try
                        {
                            if (!_disposed) ItemRemoved?.Invoke(detachedBinder);
                        }
                        finally
                        {
                            detachedBinder.Dispose();
                        }
                    });
                }
                Exception? removalError = null;
                foreach (var remove in pendingRemovals)
                {
                    try { remove(); }
                    catch (Exception ex) { removalError ??= ex; }
                }
                if (removalError != null) throw removalError;
            }
            if (!_disposed) SortBinders();
        }

        private async Task<EquipmentBinder> BuildBinderFromInventoryEquipmentUserItem(EzItemSet item, CancellationToken cancellationToken)
        {
            var model = EquipmentBinder.CreateModel((string.IsNullOrEmpty(item.ItemName) ? default(EquipmentId) : new EquipmentId(item.ItemName)), item.Name);
            ApplyInventoryEquipmentUserItemTo(model, item);
            var binder = new EquipmentBinder(model, _gs2, _session, _mountSurface: EquipmentMountSurface.InventoryEquipmentUser);
            await binder.MountAsync(cancellationToken);
            return binder;
        }

        private static void ApplyInventoryEquipmentUserItemTo(MutableEquipment model, EzItemSet item)
        {
            EquipmentBinder.ApplyUserdataInventoryEquipmentItemModel(model, item);
        }

        private EquipmentId ExtractInventoryEquipmentUserIdentity(EzItemSet item)
        {
            return (string.IsNullOrEmpty(item.ItemName) ? default(EquipmentId) : new EquipmentId(item.ItemName));
        }

        private string? ExtractInventoryEquipmentUserRowKey(EzItemSet item)
        {
            var id = ExtractInventoryEquipmentUserIdentity(item);
            if (EqualityComparer<EquipmentId>.Default.Equals(id, default)) return null;
            if (string.IsNullOrEmpty(item.ItemName) || string.IsNullOrEmpty(item.Name)) return null;
            return $"{item.ItemName}.{item.Name}";
        }

        internal sealed class EquipmentBinderComparer : IComparer<IReadOnlyEquipmentBinder>
        {
            public static readonly EquipmentBinderComparer Default = new EquipmentBinderComparer();
            public int Compare(IReadOnlyEquipmentBinder? a, IReadOnlyEquipmentBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                return Comparer<EquipmentId>.Default.Compare(a.Id, b.Id);
            }
        }

        internal sealed class EquipmentBinderIdTieBreakComparer : IComparer<IReadOnlyEquipmentBinder>
        {
            private readonly IComparer<IReadOnlyEquipmentBinder> _inner;
            public EquipmentBinderIdTieBreakComparer(IComparer<IReadOnlyEquipmentBinder> inner) { _inner = inner; }
            public int Compare(IReadOnlyEquipmentBinder? a, IReadOnlyEquipmentBinder? b)
            {
                if (a is null && b is null) return 0;
                if (a is null) return -1;
                if (b is null) return 1;
                var c = _inner.Compare(a, b);
                if (c != 0) return c;
                return Comparer<EquipmentId>.Default.Compare(a.Id, b.Id);
            }
        }
    }
}
